Integrate the glass-shroud from this design for the input form in our current design: <!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;600&family=JetBrains+Mono:wght@300&display=swap" rel="stylesheet">
    <style>
        :root {
            --bg-deep: #0a0a14;
            --prism-glow: rgba(255, 180, 220, 0.4);
            --clay-surface: #fdf2f8;
            --accent-warm: #ff8e7a;
            --text-main: #2d2d3a;
            --glass-white: rgba(255, 255, 255, 0.12);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-font-smoothing: antialiased;
        }

        body {
            background-color: var(--bg-deep);
            font-family: 'Outfit', sans-serif;
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            perspective: 1000px;
        }

        /* Cosmic Canvas */
        .universe {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: radial-gradient(circle at 20% 30%, #1a1a3a 0%, #0a0a14 100%);
            z-index: -2;
        }

        .nebula {
            position: absolute;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, var(--prism-glow) 0%, rgba(138, 43, 226, 0) 70%);
            filter: blur(80px);
            border-radius: 50%;
            animation: drift 20s infinite alternate ease-in-out;
            z-index: -1;
        }

        @keyframes drift {
            from { transform: translate(-10%, -10%) scale(1); }
            to { transform: translate(20%, 20%) scale(1.2); }
        }

        /* The Malleable Prism Container */
        .prism-suspension {
            position: relative;
            width: 100%;
            max-width: 460px;
            padding: 20px;
            transition: transform 0.6s cubic-bezier(0.23, 1, 0.32, 1);
        }

        /* Claymorphism Foundation */
        .clay-base {
            background: var(--clay-surface);
            border-radius: 50px;
            padding: 48px;
            box-shadow: 
                35px 35px 70px rgba(0, 0, 0, 0.3),
                inset 10px 10px 20px rgba(255, 255, 255, 0.8),
                inset -10px -10px 20px rgba(180, 160, 190, 0.2);
            position: relative;
            z-index: 1;
        }

        /* Glassmorphism Overlay */
        .glass-shroud {
            position: absolute;
            top: -15px;
            right: -15px;
            bottom: -15px;
            left: -15px;
            background: var(--glass-white);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border-radius: 60px;
            border: 1px solid rgba(255, 255, 255, 0.2);
            z-index: -1;
            pointer-events: none;
            mask-image: radial-gradient(circle at center, black 60%, transparent 100%);
        }

        h1 {
            font-weight: 600;
            color: var(--text-main);
            font-size: 2.2rem;
            margin-bottom: 8px;
            letter-spacing: -0.02em;
        }

        p.subtitle {
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.75rem;
            text-transform: uppercase;
            color: #8a8a9e;
            margin-bottom: 40px;
            letter-spacing: 0.1em;
        }

        .input-group {
            margin-bottom: 24px;
            position: relative;
        }

        label {
            display: block;
            font-size: 0.9rem;
            color: #6a6a7a;
            margin-bottom: 10px;
            margin-left: 12px;
            font-weight: 300;
        }

        input {
            width: 100%;
            padding: 18px 24px;
            border: none;
            border-radius: 25px;
            background: #f3e8f0;
            font-family: 'Outfit', sans-serif;
            font-size: 1rem;
            color: var(--text-main);
            box-shadow: 
                inset 4px 4px 8px rgba(0, 0, 0, 0.05),
                inset -4px -4px 8px rgba(255, 255, 255, 0.9);
            transition: all 0.3s ease;
            outline: none;
        }

        input:focus {
            box-shadow: 
                inset 2px 2px 4px rgba(0, 0, 0, 0.05),
                inset -2px -2px 4px rgba(255, 255, 255, 0.9),
                0 0 0 3px rgba(255, 142, 122, 0.2);
            background: #fff;
        }

        .login-btn {
            width: 100%;
            padding: 20px;
            margin-top: 10px;
            border: none;
            border-radius: 25px;
            background: var(--accent-warm);
            color: white;
            font-family: 'Outfit', sans-serif;
            font-weight: 600;
            font-size: 1.1rem;
            cursor: pointer;
            box-shadow: 
                0 10px 25px rgba(255, 142, 122, 0.4),
                inset 4px 4px 10px rgba(255, 255, 255, 0.3);
            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        .login-btn:hover {
            transform: translateY(-3px) scale(1.02);
            box-shadow: 
                0 15px 30px rgba(255, 142, 122, 0.5),
                inset 6px 6px 12px rgba(255, 255, 255, 0.4);
        }

        .login-btn:active {
            transform: translateY(1px) scale(0.98);
        }

        .footer-links {
            display: flex;
            justify-content: space-between;
            margin-top: 30px;
        }

        .footer-links a {
            font-size: 0.85rem;
            color: #9a9ab0;
            text-decoration: none;
            transition: color 0.3s ease;
        }

        .footer-links a:hover {
            color: var(--accent-warm);
        }

        /* Decorative Malleable Blobs */
        .blob {
            position: absolute;
            z-index: 2;
            border-radius: 50%;
            filter: blur(1px);
            pointer-events: none;
            mix-blend-mode: overlay;
        }

        .blob-1 {
            width: 80px;
            height: 80px;
            background: #ffecba;
            top: -20px;
            right: 40px;
            box-shadow: inset -10px -10px 20px rgba(0,0,0,0.1), 10px 10px 20px rgba(255,255,255,0.5);
            animation: float 6s infinite ease-in-out;
        }

        .blob-2 {
            width: 40px;
            height: 40px;
            background: #c3e9ff;
            bottom: 60px;
            left: -20px;
            box-shadow: inset -5px -5px 10px rgba(0,0,0,0.1), 5px 5px 10px rgba(255,255,255,0.5);
            animation: float 8s infinite ease-in-out reverse;
        }

        @keyframes float {
            0%, 100% { transform: translateY(0) rotate(0deg); }
            50% { transform: translateY(-20px) rotate(10deg); }
        }

        /* Entrance Animation */
        .reveal {
            opacity: 0;
            transform: translateY(30px);
            animation: revealUp 1s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        }

        @keyframes revealUp {
            to { opacity: 1; transform: translateY(0); }
        }

    </style>
</head>
<body>

    <div class="universe"></div>
    <div class="nebula"></div>

    <div class="prism-suspension reveal" id="prism">
        <div class="glass-shroud"></div>
        <div class="blob blob-1"></div>
        <div class="blob blob-2"></div>

        <main class="clay-base">
            <header>
                <h1>Welcome,</h1>
                <p class="subtitle">Presence Verification // 001</p>
            </header>

            <form onsubmit="event.preventDefault();">
                <div class="input-group">
                    <label>Identity Handle</label>
                    <input type="text" placeholder="stardust_traveler" autocomplete="off">
                </div>

                <div class="input-group">
                    <label>Access Fragment</label>
                    <input type="password" placeholder="••••••••" autocomplete="off">
                </div>

                <button class="login-btn">Initialize Descent</button>
            </form>

            <div class="footer-links">
                <a href="#">New Entity?</a>
                <a href="#">Lost Signal?</a>
            </div>
        </main>
    </div>

    <script>
        const prism = document.getElementById('prism');

        // Gentle tilt interaction
        document.addEventListener('mousemove', (e) => {
            const xAxis = (window.innerWidth / 2 - e.pageX) / 45;
            const yAxis = (window.innerHeight / 2 - e.pageY) / 45;
            prism.style.transform = `rotateY(${xAxis}deg) rotateX(${yAxis}deg)`;
        });

        // Reset on mouse leave
        document.addEventListener('mouseleave', () => {
            prism.style.transform = `rotateY(0deg) rotateX(});

        // Add haptic-style reaction to button
        const btn = document.querySelector('.login-btn');
        btn.addEventListener('mousedown', () => {
            prism.style.transform += ' scale(0.98)';
        });
        btn.addEventListener('mouseup', () => {
            prism.style.transform = prism.style.transform.replace(' scale(0.98)', '');
        });
    </script>
</body>
</html>
